const $=s=>document.querySelector(s), panel=$('#panel'), canvas=$('#scene'),ctx=canvas.getContext('2d');
const state={tab:'hunt',level:1,xp:0,next:100,hp:100,maxHp:100,damage:12,armor:4,gold:18,kills:0,bounty:0,tier:1,risk:false,weaponMastery:0,skillMastery:0,materials:{Ironbloom:3,Embercore:0,Briarhide:0,Graveglass:0},inventory:[],equipment:{weapon:null,armor:null},skills:{ash:false,harvest:false,fortune:false},player:{x:0,y:0,dir:0},enemies:[],drops:[],nodes:[],particles:[],lastAttack:0,cooldown:0,frame:0,dead:false};
const weaponBase=['Rustbound sword','Cairn cleaver','Wayfarer’s edge','Briarhook'];
const prefixes=[['Keen',1.18],['Hollow',1.1],['Ember-woken',1.26],['Grave-touched',1.15],['Feral',1.2],['Warden’s',1.13]];
const suffixes=['of the lost','of cinders','of the deep road','of hunger','of the thorn','of last light'];
const matNames=Object.keys(state.materials);
const roman=n=>['I','II','III','IV','V','VI'][Math.min(5,n-1)];
function rand(a,b){return Math.random()*(b-a)+a}function choose(a){return a[Math.floor(Math.random()*a.length)]}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),1900)}
function gearRoll(force=false){let r=Math.random(),rarity=r<.025?'legendary':r<.18?'rare':r<.57?'magic':'common';if(force)rarity='rare';let b=state.level*1.6+state.tier*2,base=Math.round(rand(b*.7,b*1.4));let aff=rarity==='common'?null:choose(prefixes);return {id:Date.now()+Math.random(),name:`${aff?aff[0]+' ':''}${choose(weaponBase)}${rarity==='common'?'':' '+choose(suffixes)}`,rarity,damage:base+(aff?Math.round(base*(aff[1]-1)):0),armor:Math.round(rand(0,state.tier+1)),affix:aff?aff[0]+' · '+choose(['+ vitality','+ attack speed','+ ember damage','+ find chance']):'Unmarked iron',type:Math.random()<.78?'weapon':'armor'}}
function setTab(tab){state.tab=tab;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderPanel()}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
function renderPanel(){let h='';if(state.tab==='hunt'){h=`<div class="section-title">THE HUNT <small>${state.kills} slain</small></div><div class="item"><div class="item-head"><span class="item-name">A living frontier</span><span class="rarity common">TIER ${roman(state.tier)}</span></div><p>Stalk the briar-stalkers, strip the wilds for parts, and push deeper when your pack is full. Threat scales with each tier.</p><div class="item-actions"><button class="smallbtn" onclick="changeTier(-1)">− TIER</button><button class="smallbtn gold" onclick="changeTier(1)">DESCEND +</button></div></div><div class="section-title" style="margin-top:19px">FIELD NOTES <small>LIVE</small></div><div class="material-row"><span>Creatures culled</span><span>${state.kills}</span></div><div class="material-row"><span>Weapon practice</span><span>${Math.floor(state.weaponMastery)}%</span></div><div class="material-row"><span>Ground gathered</span><span>${state.materials.Ironbloom} Ironbloom</span></div><div class="quest"><strong>Roadside bounty</strong><p>Slay six briar-stalkers · <b>${state.bounty}/6</b></p><progress value="${state.bounty}" max="6"></progress></div><div class="item" style="margin-top:14px"><div class="item-head"><span class="item-name">Risk of the forsaken</span><span class="rarity legendary">${state.risk?'ACTIVE':'OPTIONAL'}</span></div><p>${state.risk?'Enemies hit harder. Rare loot and materials are doubled, but death costs 15% of carried coin.':'Turn on the risk modifier for doubled rare finds. Death costs a portion of your coin.'}</p></div>`}
if(state.tab==='gear'){h=`<div class="section-title">WORN RELICS <small>LOADOUT</small></div>${['weapon','armor'].map(t=>{let it=state.equipment[t];return `<div class="item"><div class="item-head"><span class="item-name">${t==='weapon'?'MAIN HAND':'BODY'}</span><span class="rarity ${it?it.rarity:'common'}">${it?it.rarity:'EMPTY'}</span></div><p>${it?`${it.name}<br>${t==='weapon'?`+${it.damage} attack`:`+${it.armor} armor`} · ${it.affix}`:'No relic equipped. Find a drop in the wilds.'}</p></div>`}).join('')}<div class="section-title" style="margin-top:16px">PACK <small>${state.inventory.length} / 16</small></div>${state.inventory.length?state.inventory.slice(0,12).map((it,i)=>`<div class="item"><div class="item-head"><span class="item-name">${it.name}</span><span class="rarity ${it.rarity}">${it.rarity}</span></div><p>⚔ ${it.damage} damage · ◈ ${it.armor} armor · ${it.affix}</p><div class="item-actions"><button class="smallbtn gold" onclick="equipItem(${i})">EQUIP</button><button class="smallbtn" onclick="salvage(${i})">SALVAGE +${Math.max(1,it.damage)}g</button></div></div>`).join(''):'<div class="empty">Your pack is quiet. The wilds are not.</div>'}`}
if(state.tab==='forge'){h=`<div class="section-title">THE FIELD FORGE <small>CRAFTING</small></div><p style="font-size:9px;color:#99998e;line-height:1.6;margin:0 0 12px">Salvage relics. Hunt components. Turn a hundred small finds into one impossible thing.</p><div class="item"><div class="item-head"><span class="item-name">Forge a Warden’s relic</span><span class="rarity rare">RARE</span></div><p>Guarantees a rare relic, scaled to your delve. Requires 5 Ironbloom, 3 Briarhide, 2 Embercore & 40g.</p><div class="item-actions"><button class="smallbtn gold" onclick="craft()">FORGE RELIC</button></div></div><div class="section-title" style="margin-top:18px">GATHERED STOCK <small>COMPONENTS</small></div>${matNames.map(n=>`<div class="material-row"><span>${n}</span><span>${state.materials[n]}</span></div>`).join('')}<div class="item" style="margin-top:15px"><div class="item-head"><span class="item-name">Field tonic</span><span class="rarity common">CONSUMABLE</span></div><p>Restore 45 vitality. A desperate hedge against a careless delve.</p><div class="item-actions"><button class="smallbtn" onclick="buyPotion()">BREW · 12g</button></div></div>`}
if(state.tab==='mastery'){h=`<div class="section-title">NON-LINEAR MASTERY <small>${state.level} INSIGHT</small></div><p style="font-size:9px;color:#99998e;line-height:1.6;margin:0 0 12px">Practice grows mastery. Spend insight on any unlocked branch; respec freely at camp.</p><div class="item"><div class="item-head"><span class="item-name">Wayfarer’s edge</span><span class="rarity rare">WEAPON · ${Math.floor(state.weaponMastery)}%</span></div><div class="bar" style="margin-top:9px"><i style="width:${Math.min(100,state.weaponMastery)}%;background:#c9a75f"></i></div><p>Every strike sharpens this weapon mastery. +1% attack per 10% mastery.</p></div><div class="item"><div class="item-head"><span class="item-name">Ashen burst</span><span class="rarity rare">SKILL · ${Math.floor(state.skillMastery)}%</span></div><div class="bar" style="margin-top:9px"><i style="width:${Math.min(100,state.skillMastery)}%;background:#c57950"></i></div><p>Press Q to scorch nearby foes. Practice increases its force. ${state.skills.ash?'+25% burst radius unlocked.':'Unlock this node for 1 insight.'}</p>${!state.skills.ash?'<div class="item-actions"><button class="smallbtn" onclick="unlockSkill(\'ash\')">UNLOCK · 1 INSIGHT</button></div>':''}</div><div class="skill ${state.skills.harvest?'':'locked'}"><div class="skillicon">⌁</div><div><strong>Prospector’s instinct</strong><small>Gather extra minerals · ${state.skills.harvest?'learned':'1 insight'}</small></div>${!state.skills.harvest?'<button class="smallbtn" onclick="unlockSkill(\'harvest\')">＋</button>':''}</div><div class="skill ${state.skills.fortune?'':'locked'}"><div class="skillicon">✧</div><div><strong>Greedy hands</strong><small>+8% rare drop chance · ${state.skills.fortune?'learned':'2 insight'}</small></div>${!state.skills.fortune?'<button class="smallbtn" onclick="unlockSkill(\'fortune\')">＋2</button>':''}</div><div class="section-title" style="margin-top:18px">FIELD PRACTICE <small>USE IT TO GROW</small></div><div class="material-row"><span>Weapon proficiency</span><span>${Math.floor(state.weaponMastery)}%</span></div><div class="material-row"><span>Skill proficiency</span><span>${Math.floor(state.skillMastery)}%</span></div>`}
if(state.tab==='bounties'){h=`<div class="section-title">ROADSIDE CAMP <small>NO OATHS REQUIRED</small></div><div class="item"><div class="item-head"><span class="item-name">Talla’s trail ration</span><span class="rarity common">SUPPORT</span></div><p>Wandering quartermaster. Take a quick bounty for a focused XP burst and a temporary relic—then get back to the hunt.</p><div class="quest"><strong>Briar-clearing run · ${state.bounty}/6</strong><p>Kill any six creatures. Reward: 85 XP + a rare milestone relic.</p><progress value="${state.bounty}" max="6"></progress></div>${state.bounty>=6?'<button class="smallbtn gold" onclick="claimBounty()">CLAIM REWARD</button>':'<button class="smallbtn" onclick="toast(\'Talla: Six briar-stalkers. No need to hurry back.\')">ACCEPT BOUNTY</button>'}</div><div class="item"><div class="item-head"><span class="item-name">Borrowed ward</span><span class="rarity magic">MILESTONE</span></div><p>When you reach level 3, Talla leaves a temporary ward at camp. It lasts until the next tier descent.</p><div class="material-row"><span>Milestone</span><span>${state.level>=3?'READY':'LEVEL 03'}</span></div></div><div class="section-title" style="margin-top:18px">DELVING CONTRACTS <small>OPTIONAL</small></div><div class="item"><div class="item-head"><span class="item-name">Graveglass weather</span><span class="rarity legendary">RISK</span></div><p>Darkness crowds the verge. Foes gain 40% vitality, but rare drops appear twice as often. Your purse is forfeit in death.</p><div class="item-actions"><button class="smallbtn ${state.risk?'gold':''}" onclick="toggleRisk()">${state.risk?'ABANDON CONTRACT':'ENTER CONTRACT'}</button></div></div>`}
panel.innerHTML=h}

