function updateHud(){ $('#level').textContent=String(state.level).padStart(2,'0');$('#xpText').textContent=`${state.xp} / ${state.next}`;$('#xpBar').style.width=`${Math.min(100,state.xp/state.next*100)}%`;$('#hpText').textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;$('#hpBar').style.width=`${Math.max(0,state.hp/state.maxHp*100)}%`;$('#damage').textContent=Math.round(state.damage+(state.equipment.weapon?.damage||0)*(1+state.weaponMastery/100));$('#armor').textContent=state.armor+(state.equipment.armor?.armor||0);$('#gold').textContent=state.gold;$('#tier').textContent=roman(state.tier);$('#questCount').textContent=`${state.bounty} / 6`;$('#objectiveText').textContent=state.bounty>=6?'Bounty ready · visit camp':`Cull the briar-stalkers`;$('#threatText').textContent=state.risk?'SEVERE':'LOW';$('#riskToggle').classList.toggle('on',state.risk)}
function gainXp(n){state.xp+=n;while(state.xp>=state.next){state.xp-=state.next;state.level++;state.next=Math.floor(state.next*1.35);state.maxHp+=12;state.hp=Math.min(state.maxHp,state.hp+30);state.damage+=2;toast(`LEVEL ${state.level} · Insight earned`)}updateHud()}
function changeTier(d){state.tier=Math.max(1,Math.min(6,state.tier+d));state.enemies=[];state.drops=[];state.player.x=0;state.player.y=0;for(let i=0;i<5+state.tier;i++)spawnEnemy();toast(`Delve tier ${roman(state.tier)} · the wilds stir`);updateHud();renderPanel()}
function spawnEnemy(){let w=canvas.clientWidth||800,h=canvas.clientHeight||600;let a=rand(0,Math.PI*2),r=rand(Math.min(w,h)*.34,Math.min(w,h)*.52);state.enemies.push({x:w/2+Math.cos(a)*r,y:h/2+Math.sin(a)*r,r:rand(13,17),hp:24+state.tier*9,max:24+state.tier*9,speed:rand(18,30)+state.tier*2,hit:0,kind:Math.random()<.25?'ember wisp':'briar-stalker'})}
function seedNodes(){state.nodes=[];let w=canvas.clientWidth||800,h=canvas.clientHeight||600;for(let i=0;i<11;i++){let x=rand(60,w-60),y=rand(80,h-70);if(Math.hypot(x-w/2,y-h/2)>95)state.nodes.push({x,y,r:rand(8,12),type:choose(matNames),taken:false})}}
function resize(){let r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);ctx.setTransform(d,0,0,d,0,0);if(!state.ready){state.player.x=r.width/2;state.player.y=r.height/2;state.ready=true;seedNodes();for(let i=0;i<6;i++)spawnEnemy()}}
function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;ctx.clearRect(0,0,w,h);ctx.fillStyle='#20281f';ctx.fillRect(0,0,w,h);
// moody forest floor texture
for(let y=0;y<h;y+=42)for(let x=0;x<w;x+=42){let n=((x*17+y*31)%13);ctx.fillStyle=n<3?'#293128':n<6?'#232b23':'#20281f';ctx.fillRect(x+((y/42|0)%2)*19,y,40,40);}
