for(let i=0;i<13;i++){let x=(i*239+101)%w,y=(i*151+71)%h;if(Math.hypot(x-state.player.x,y-state.player.y)<37)continue;let s=rand(18,33);ctx.fillStyle='#111813';ctx.beginPath();ctx.ellipse(x+3,y+8,s*.72,s*.42,0,0,7);ctx.fill();ctx.fillStyle=i%3?'#27372a':'#30382a';ctx.beginPath();ctx.arc(x,y,s,0,7);ctx.fill();ctx.fillStyle='#485039';ctx.beginPath();ctx.arc(x-s*.32,y-s*.28,s*.38,0,7);ctx.fill();ctx.strokeStyle='#69704a';ctx.lineWidth=1;for(let k=0;k<4;k++){ctx.beginPath();ctx.moveTo(x+rand(-s,s),y+rand(-s,s));ctx.lineTo(x+rand(-s,s),y+rand(-s,s));ctx.stroke()}}
// glowing gatherables
state.nodes.forEach(n=>{if(n.taken)return;ctx.fillStyle=n.type==='Embercore'?'#d87543':n.type==='Graveglass'?'#7499bd':'#a7a969';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=8;ctx.beginPath();ctx.moveTo(n.x,n.y-n.r);ctx.lineTo(n.x+n.r*.7,n.y);ctx.lineTo(n.x,n.y+n.r);ctx.lineTo(n.x-n.r*.7,n.y);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#eee0a6';ctx.fillRect(n.x-1,n.y-1,2,2)});
// loot motes
state.drops.forEach(d=>{ctx.fillStyle=d.item.rarity==='legendary'?'#e98a54':d.item.rarity==='rare'?'#ddc36e':d.item.rarity==='magic'?'#8bb6e9':'#c8c5b5';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=12;ctx.beginPath();ctx.arc(d.x,d.y,5,0,7);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff';ctx.fillRect(d.x-1,d.y-1,2,2)});
// enemies
state.enemies.forEach(e=>{ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(e.x,e.y+8,e.r*1.1,e.r*.53,0,0,7);ctx.fill();ctx.fillStyle=e.kind==='ember wisp'?'#c86d42':'#8c5744';ctx.beginPath();ctx.arc(e.x,e.y,e.r,0,7);ctx.fill();ctx.fillStyle=e.kind==='ember wisp'?'#ffc278':'#d6a86e';ctx.beginPath();ctx.arc(e.x-4,e.y-2,2,0,7);ctx.arc(e.x+4,e.y-2,2,0,7);ctx.fill();if(e.hp<e.max){ctx.fillStyle='#301d1a';ctx.fillRect(e.x-15,e.y-e.r-8,30,3);ctx.fillStyle='#d2644c';ctx.fillRect(e.x-15,e.y-e.r-8,30*e.hp/e.max,3)}if(e.hit>0){ctx.strokeStyle='#ffd38a';ctx.lineWidth=2;ctx.beginPath();ctx.arc(e.x,e.y,e.r+4,0,7);ctx.stroke()}});
