input.newString:
function attack(){let now=performance.now();if(now-state.lastAttack<430)return;state.lastAttack=now;state.weaponMastery=Math.min(100,state.weaponMastery+.7);let p=state.player,near=state.enemies.filter(e=>Math.hypot(e.x-p.x,e.y-p.y)<75).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(near){near.hp-=Math.round(state.damage+(state.equipment.weapon?.damage||0)*(1+state.weaponMastery/100));near.hit=.14;let d=Math.hypot(near.x-p.x,near.y-p.y)||1;near.x+=(near.x-p.x)/d*13;near.y+=(near.y-p.y)/d*13;state.particles.push({x:near.x,y:near.y,color:'#ffd18b',life:.35});if(near.hp<=0)killEnemy(near)}else{state.particles.push({x:p.x+Math.cos(p.dir)*29,y:p.y+Math.sin(p.dir)*29,color:'#c8b787',life:.17})}updateHud()}
function killEnemy(e){state.enemies.splice(state.enemies.indexOf(e),1);state.kills++;state.bounty=Math.min(6,state.bounty+1);gainXp(20+state.tier*4);let chance=state.risk?.95:.78;if(state.skills.fortune)chance=Math.min(.99,chance+.08);if(Math.random()<chance){let item=gearRoll();if(state.risk&&Math.random()<.14)item=gearRoll(true);state.drops.push({x:e.x,y:e.y,item})}let m=choose(['Briarhide','Ironbloom','Embercore','Graveglass']);if(Math.random()<(state.risk?.9:.48))state.materials[m]++;if(Math.random()<.4)state.gold+=Math.round(rand(2,7)*state.tier);if(state.enemies.length<6+state.tier)setTimeout(()=>{if(state.enemies.length<8+state.tier)spawnEnemy()},1200);if(state.bounty===6)toast('Bounty complete · return to camp');updateHud();if(state.tab==='hunt'||state.tab==='bounties')renderPanel()}
function skill(){if(state.cooldown>0){toast(`Ashen burst · ${Math.ceil(state.cooldown)}s`);return}state.cooldown=8;state.skillMastery=Math.min(100,state.skillMastery+3);let p=state.player,r=state.skills.ash?135:90,count=0;state.enemies.slice().forEach(e=>{if(Math.hypot(e.x-p.x,e.y-p.y)<r){e.hp-=Math.round(22+state.skillMastery*.35+state.tier*3);e.hit=.25;count++;if(e.hp<=0)killEnemy(e)}});state.particles.push({x:p.x,y:p.y,color:'#ff9c5e',life:.55,r});toast(count?`Ashen burst · ${count} caught in the flare`:'Ash gathers around you');renderPanel()}
function interact(){let p=state.player;let d=state.drops.map(x=>({...x,dist:Math.hypot(x.x-p.x,x.y-p.y)})).filter(x=>x.dist<72).sort((a,b)=>a.dist-b.dist)[0];if(d){state.inventory.unshift(d.item);state.drops.splice(state.drops.indexOf(d),1);toast(`${d.item.rarity.toUpperCase()} · ${d.item.name}`);renderPanel();return}let n=state.nodes.filter(x=>!x.taken&&Math.hypot(x.x-p.x,x.y-p.y)<65).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(n){n.taken=true;let amt=1+(state.skills.harvest&&Math.random()<.65?1:0);state.materials[n.type]+=amt;gainXp(5);toast(`Gathered ${amt} ${n.type}`);renderPanel();return}toast('Nothing close enough to gather')}
function equipItem(i){let it=state.inventory.splice(i,1)[0];let slot=it.type==='weapon'?'weapon':'armor';if(state.equipment[slot])state.inventory.push(state.equipment[slot]);state.equipment[slot]=it;toast(`${it.name} equipped`);updateHud();renderPanel()}
function salvage(i){let it=state.inventory.splice(i,1)[0],value=Math.max(1,it.damage);state.gold+=value;state.materials.Ironbloom+=it.rarity==='legendary'?4:it.rarity==='rare'?2:1;if(Math.random()<.3)state.materials.Embercore++;toast(`Salvaged · +${value}g · components recovered`);updateHud();renderPanel()}
function craft(){if(state.materials.Ironbloom<5||state.materials.Briarhide<3||state.materials.Embercore<2||state.gold<40){toast('The forge needs more components');return}state.materials.Ironbloom-=5;state.materials.Briarhide-=3;state.materials.Embercore-=2;state.gold-=40;let item=gearRoll(true);item.name='Warden’s '+item.name;state.inventory.unshift(item);toast('The forge remembers · rare relic made');updateHud();renderPanel()}
function buyPotion(){if(state.gold<12){toast('Not enough coin');return}state.gold-=12;state.hp=Math.min(state.maxHp,state.hp+45);toast('Field tonic · vitality restored');updateHud()}
function unlockSkill(id){let cost=id==='fortune'?2:1;if(state.level<cost+1){toast(`Need ${cost+1} insight · gain a level`);return}state.skills[id]=true;toast('Mastery branch unlocked');renderPanel()}
function claimBounty(){if(state.bounty<6)return;state.bounty=0;gainXp(85);let it=gearRoll(true);it.name='Talla’s '+it.name;state.inventory.unshift(it);toast('Bounty claimed · XP and a rare relic');updateHud();renderPanel()}
function toggleRisk(){state.risk=!state.risk;toast(state.risk?'Contract accepted · death will cost coin':'Contract abandoned');updateHud();renderPanel()}
$('#riskToggle').onclick=toggleRisk;$('#menuBtn').onclick=()=>$('#side').classList.toggle('open');$('#journalBtn').onclick=()=>{$('#side').classList.add('open');setTab('bounties')};$('#soundBtn').onclick=e=>{e.currentTarget.textContent=e.currentTarget.textContent==='♪'?'♫':'♪';toast('The wilds keep their own music')};
function heal(){if(state.hp<state.maxHp)buyPotion();else toast('Vitality already full')}
const keys={};window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['w','a','s','d',' ','q','e','1'].includes(k))e.preventDefault();keys[k]=true;if(k==='q')skill();if(k==='e')interact();if(k==='1')heal();if(k===' '||k==='j')attack();if(k==='i'){$('#side').classList.toggle('open')}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('pointerdown',e=>{let r=canvas.getBoundingClientRect(),p=state.player,x=e.clientX-r.left,y=e.clientY-r.top;state.player.dir=Math.atan2(y-p.y,x-p.x);attack()});
let moveInterval={};document.querySelectorAll('.pad [data-dir]').forEach(b=>{let dir=b.dataset.dir;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[dir==='up'?'w':dir==='down'?'s':dir==='left'?'a':'d']=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys[dir==='up'?'w':dir==='down'?'s':dir==='left'?'a':'d']=false))});$('#touchAttack').onclick=attack;$('#touchSkill').onclick=skill;$('#touchInteract').onclick=interact;
let last=performance.now();function loop(now){let dt=Math.min(.05,(now-last)/1000);last=now;state.frame++;if(state.cooldown>0)state.cooldown-=dt;let p=state.player,dx=(keys.d||keys.right?1:0)-(keys.a||keys.left?1:0),dy=(keys.s||keys.down?1:0)-(keys.w||keys.up?1:0),mag=Math.hypot(dx,dy);if(mag){p.x+=dx/mag*170*dt;p.y+=dy/mag*170*dt;p.x=Math.max(18,Math.min(canvas.clientWidth-18,p.x));p.y=Math.max(18,Math.min(canvas.clientHeight-18,p.y));p.dir=Math.atan2(dy,dx)}state.enemies.forEach(e=>{let vx=p.x-e.x,vy=p.y-e.y,d=Math.hypot(vx,vy)||1;if(d>22){e.x+=vx/d*e.speed*dt;e.y+=vy/d*e.speed*dt}else if(Math.random()<dt*1.1){let dmg=Math.max(1,Math.round((state.risk?12:8)+state.tier*2-(state.armor+(state.equipment.armor?.armor||0))*.55));state.hp-=dmg;state.particles.push({x:p.x+rand(-8,8),y:p.y,color:'#d86651',life:.35});updateHud();if(state.hp<=0)death()}});state.enemies.forEach(e=>e.hit=Math.max(0,e.hit-dt));state.particles=state.particles.filter(a=>{a.life-=dt;if(a.r){a.r+=220*dt}return a.life>0});draw();if(state.frame%180===0){let d=new Date();$('#clock').textContent=`DAY ${String(4+Math.floor(state.frame/900)).padStart(2,'0')} · ${String(19+Math.floor(state.frame/1800)%4).padStart(2,'0')}:${String(Math.floor(state.frame/3)%60).padStart(2,'0')}`}requestAnimationFrame(loop)}
function death(){if(state.dead)return;state.dead=true;state.gold=Math.floor(state.gold*(state.risk?.85:.95));state.hp=state.maxHp;state.player.x=canvas.clientWidth/2;state.player.y=canvas.clientHeight/2;state.dead=false;toast(`You wake at the verge · ${state.risk?'15%':'5%'} coin lost`);updateHud()}
window.addEventListener('resize',()=>{resize();state.player.x=Math.min(canvas.clientWidth-20,Math.max(20,state.player.x));state.player.y=Math.min(canvas.clientHeight-20,Math.max(20,state.player.y))});
resize();updateHud();renderPanel();requestAnimationFrame(loop);
</script></body></html>

