// enemies
state.enemies.forEach(e=>{ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(e.x,e.y+8,e.r*1.1,e.r*.53,0,0,7);ctx.fill();ctx.fillStyle=e.kind==='ember wisp'?'#c86d42':'#8c5744';ctx.beginPath();ctx.arc(e.x,e.y,e.r,0,7);ctx.fill();ctx.fillStyle=e.kind==='ember wisp'?'#ffc278':'#d6a86e';ctx.beginPath();ctx.arc(e.x-4,e.y-2,2,0,7);ctx.arc(e.x+4,e.y-2,2,0,7);ctx.fill();if(e.hp<e.max){ctx.fillStyle='#301d1a';ctx.fillRect(e.x-15,e.y-e.r-8,30,3);ctx.fillStyle='#d2644c';ctx.fillRect(e.x-15,e.y-e.r-8,30*e.hp/e.max,3)}if(e.hit>0){ctx.strokeStyle='#ffd38a';ctx.lineWidth=2;ctx.beginPath();ctx.arc(e.x,e.y,e.r+4,0,7);ctx.stroke()}});
// player + targeting aura
let p=state.player;ctx.fillStyle='#0008';ctx.beginPath();ctx.ellipse(p.x,p.y+9,13,6,0,0,7);ctx.fill();ctx.fillStyle='#c2a376';ctx.beginPath();ctx.arc(p.x,p.y,11,0,7);ctx.fill();ctx.fillStyle='#ddd0ac';ctx.beginPath();ctx.arc(p.x,p.y-2,6,0,7);ctx.fill();ctx.fillStyle='#493f31';ctx.beginPath();ctx.moveTo(p.x-8,p.y-3);ctx.lineTo(p.x,p.y-15);ctx.lineTo(p.x+8,p.y-3);ctx.fill();ctx.strokeStyle='#c5b074';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x+8,p.y);ctx.lineTo(p.x+18,p.y-7);ctx.stroke();
// vignette
let g=ctx.createRadialGradient(w/2,h/2,Math.min(w,h)*.18,w/2,h/2,Math.max(w,h)*.7);g.addColorStop(0,'#0000');g.addColorStop(1,'#060a08bb');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
state.particles.forEach(a=>{ctx.globalAlpha=Math.max(0,a.life);ctx.fillStyle=a.color;ctx.fillRect(a.x,a.y,3,3)});ctx.globalAlpha=1;
}

